#include "live_mesh_read.hpp"
int main(int argc,char** argv)try{
 if(argc!=4)throw std::invalid_argument("Usage: tm2020_live_mesh_inventory manifest maxMB inventory.jsonl");tm2020::live::ReadOnlyObserver identity(argv[1]);const auto max_mb=std::stoull(argv[2]);if(max_mb<64||max_mb>16384)throw std::invalid_argument("Invalid scan limit");Reader p{OpenProcess(PROCESS_VM_READ|PROCESS_QUERY_LIMITED_INFORMATION,FALSE,identity.process_id())};if(!p.h)throw std::runtime_error("Read-only open denied");verify_pinned_build(p);std::map<std::uintptr_t,Mesh> meshes;std::uint64_t candidates{},validated{};
 const auto scanned=scan(p,max_mb,[&](std::uintptr_t base,std::span<const std::byte> data){for(std::size_t at=0;at+sizeof(Mesh)<=data.size();at+=8){std::uint32_t type{};std::memcpy(&type,data.data()+at+12,4);if(type!=7)continue;Mesh m;std::memcpy(&m,data.data()+at,sizeof(m));if(m.vertices.count<3||m.vertices.count>1000000||!m.cooked_triangles.count||m.cooked_triangles.count>2000000||!m.tree.count||m.tree.count>4000000||!pointer(m.vertices.pointer)||!pointer(m.cooked_triangles.pointer)||!pointer(m.tree.pointer))continue;candidates++;bool good=true;for(unsigned k=0;k<std::min(8u,m.cooked_triangles.count);k++){CookedTriangle t{};if(!p.get(m.cooked_triangles.pointer+k*32,t)||!finite(t.normal)||!std::isfinite(t.plane_constant)||std::abs(t.plane_constant)>1e6){good=false;break;}float norm=(t.normal[0]*t.normal[0]+t.normal[1]*t.normal[1])+t.normal[2]*t.normal[2];if(norm!=0&&std::abs(norm-1)>1e-3){good=false;break;}for(auto index:t.vertices){std::array<float,3> point{};if(index>=m.vertices.count||!p.get(m.vertices.pointer+index*12,point)||!finite(point)){good=false;break;}}if(!good)break;}AabbNode root{};if(!good||!p.get(m.tree.pointer,root)||!finite(root.center)||!finite(root.half_extent))continue;for(float x:root.half_extent)good=good&&x>=0;if(!good)continue;if(root.packed&1){if((root.packed>>1)>=m.cooked_triangles.count)continue;}else if(!(root.packed>>1)||(root.packed>>1)>m.tree.count)continue;meshes.emplace(base+at,m);}});
 std::ofstream out(argv[3]);out<<std::setprecision(9)<<"{\"schema\":\"tm2020_live_mesh_inventory_v1\",\"pid\":"<<identity.process_id()<<",\"readOnly\":true,\"meshType\":7,\"scannedMB\":"<<scanned/1048576<<",\"typedHeaderCandidates\":"<<candidates<<",\"validatedSampledMeshes\":"<<meshes.size()<<",\"worldPlacementVerified\":false}\n";for(const auto& [address,m]:meshes){out<<"{\"mesh\":\"0x"<<std::hex<<address<<"\",\"vertices\":\"0x"<<m.vertices.pointer<<"\",\"triangles\":\"0x"<<m.cooked_triangles.pointer<<"\",\"tree\":\"0x"<<m.tree.pointer<<std::dec<<"\",\"vertexCount\":"<<m.vertices.count<<",\"triangleCount\":"<<m.cooked_triangles.count<<",\"treeNodes\":"<<m.tree.count<<"}\n";}out.flush();if(!out)throw std::runtime_error("Cannot save inventory");std::cout<<"PASS LIVE_MESH_INVENTORY candidates="<<candidates<<" sampled_valid_meshes="<<meshes.size()<<" scannedMB="<<scanned/1048576<<" world_placement_unverified=true\n";
return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
